-- Merge Two Sorted Arrays (Easy)
INSERT INTO coding_problems (slug, title, description, difficulty, category, type, tags, starter_code, test_cases, examples, constraints, points, order_index, time_limit_ms, memory_limit_kb, input_format, output_format, editorial, judged)
VALUES ($q$merge-sorted-arrays$q$, $q$Merge Two Sorted Arrays$q$, $q$Two arrays are each sorted in non-decreasing order. Merge them into one array that is also sorted in non-decreasing order, in linear time. Either array can be empty.$q$, $q$Easy$q$, $q$Arrays$q$, 'code', ARRAY[$q$array$q$, $q$two-pointers$q$]::text[], $q${"python": "import sys\n\n\ndef main():\n    lines = sys.stdin.read().split('\\n')\n    # Input:\n    # Line 1: n and m.\n    # Line 2: n integers (empty when n = 0).\n    # Line 3: m integers (empty when m = 0).\n    # TODO: solve, then print the answer\n\n\nmain()\n", "javascript": "const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\n// Input:\n// Line 1: n and m.\n// Line 2: n integers (empty when n = 0).\n// Line 3: m integers (empty when m = 0).\n// TODO: solve, then console.log the answer\n", "java": "import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        List<String> lines = new ArrayList<>();\n        for (String s; (s = in.readLine()) != null; ) lines.add(s);\n        // Input:\n        // Line 1: n and m.\n        // Line 2: n integers (empty when n = 0).\n        // Line 3: m integers (empty when m = 0).\n        // TODO: solve, then System.out.println the answer\n    }\n}\n", "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // Input:\n    // Line 1: n and m.\n    // Line 2: n integers (empty when n = 0).\n    // Line 3: m integers (empty when m = 0).\n    // TODO: read with cin / getline, solve, print the answer\n    return 0;\n}\n", "c": "#include <stdio.h>\n\nint main(void) {\n    // Input:\n    // Line 1: n and m.\n    // Line 2: n integers (empty when n = 0).\n    // Line 3: m integers (empty when m = 0).\n    /* TODO: read with scanf / fgets, solve, print the answer */\n    return 0;\n}\n"}$q$::jsonb, '[]'::jsonb, $q$[{"input": "3 3\n1 4 9\n2 3 10", "output": "1 2 3 4 9 10", "explanation": ""}, {"input": "0 2\n\n5 6", "output": "5 6", "explanation": "The first array is empty, so its line is blank."}]$q$::jsonb, ARRAY[$q$0 ≤ n, m ≤ 5 000$q$, $q$-10^9 ≤ values ≤ 10^9$q$]::text[], 10, 1007, 2000, 262144, $q$Line 1: n and m.
Line 2: n integers (empty when n = 0).
Line 3: m integers (empty when m = 0).$q$, $q$The merged array on one line, separated by spaces. Print an empty line when both are empty.$q$, $q$Keep one pointer in each array. Repeatedly copy the smaller front element and advance that pointer; when one array runs out, copy the rest of the other. O(n + m). Sorting the concatenation also passes at these sizes, but the two-pointer merge is the intended solution.$q$, false)
ON CONFLICT (slug) DO NOTHING;

